    async getAll(): Promise<Feature[]> {
        let snapshot = await this.collection.get();

        if (snapshot.empty) {
            const batch = adminDb.batch();
            defaultFeatures.forEach(feature => {
                const docRef = this.collection.doc(feature.id);
                batch.set(docRef, feature);
            });
