  19  */
  20 export async function readFileContent(file: File): Promise<string> {
  21     return new Promise((resolve, reject) => {
  22         const reader = new FileReader();
  23 
  24         reader.onabort = () => reject(new Error('File reading was aborted.'));
  25         reader.onerror = () => reject(new Error('Failed to read file.'));
  26         reader.onload = () => {
  27             resolve(reader.result as string);
  28         };
  29 
  30         const isTextFile = file.type.startsWith('text/') || file.name.endsWith('.md');
  31         if (isTextFile) {
  32             reader.readAsText(file);
  33         } else {
  34             reader.readAsDataURL(file);
  35         }
  36     });
