  16 import { convertMarkdownToPdf } from '@/lib/utils/pdf-utils';
  17 import type { TransactionProperties } from '@/lib/types';
  18 
  19 function formatTransactionsToMarkdown(transactions: TransactionProperties[], dateRange: DateRange): string {
  20     let markdown = `# Financial Report\n\n`;
  21     if (dateRange.from && dateRange.to) {
  22         markdown += `**Date Range:** ${format(dateRange.from, "LLL dd, y")} - ${format(dateRange.to, "LLL dd, y")}\n\n`;
  23     }
  24     
  25     markdown += `| Transaction ID | User Name | Plan | Amount | Status | Date |\n`;
  26     markdown += `|---|---|---|---|---|---|\n`;
  27 
  28     let totalVerified = 0;
  29     transactions.forEach(t => {
  30         markdown += `| ${t.id.slice(0, 8)} | ${t.userName} | ${t.planName} | $${t.price.toFixed(2)} | ${t.status} | ${new Date(t.createdAt).toLocaleDateString()} |\n`;
  31         if (t.status === 'verified') {
  32             totalVerified += t.price;
  33         }
  34     });
  35 
  36     markdown += `\n## Summary\n\n`;
  37     markdown += `- **Total Transactions:** ${transactions.length}\n`;
  38     markdown += `- **Total Verified Revenue:** $${totalVerified.toFixed(2)}\n`;
  39 
  40     return markdown;
  41 }
  42 
  43 
