   3 import { useState } from 'react';
   4 import { useMutation } from '@tanstack/react-query';
   5 import { useAuth } from '@/context/AuthContext';
   6 import { useBuilderStore } from '../core/useBuilderStore';
   7 import { apiService } from '@/infrastructure/api/ApiService';
   8 
   9 interface Message {
  10     role: 'user' | 'model';
  11     content: string;
  12 }
  13 
  14 export function useProjectChat() {
  15     const [messages, setMessages] = useState<Message[]>([]);
  16     const { firebaseUser } = useAuth();
  17     const { project } = useBuilderStore();
  18 
  19     const mutation = useMutation({
  20         mutationFn: async (userMessage: string) => {
  21             if (!firebaseUser || !project) throw new Error('User or project not available');
  22             const token = await firebaseUser.getIdToken();
  23             const projectContext = project.fullMarkdownContent;
  24 
  25             return apiService<any, { response: string }>({
  26                 endpoint: '/api/chat/project-consultant',
  27                 method: 'POST',
  28                 token,
  29                 data: {
  30                     projectContext,
  31                     userMessage,
  32                     history: messages,
  33                 },
  34             });
  35         },
  36         onSuccess: (data) => {
  37             setMessages(prev => [...prev, { role: 'model', content: data.response }]);
  38         },
  39         onError: (error: Error) => {
  40              setMessages(prev => [...prev, { role: 'model', content: `Sorry, an error occurred: ${error.message}` }]);
  41         },
  42     });
  43 
  44     const sendMessage = (message: string) => {
  45         if (!message.trim() || mutation.isPending) return;
  46 
  47         const newUserMessage: Message = { role: 'user', content: message };
  48         setMessages(prev => [...prev, newUserMessage]);
  49         mutation.mutate(message);
  50     };
  51 
  52     return {
  53         messages,
  54         sendMessage,
  55         isLoading: mutation.isPending,
  56     };
  57 }
  58 
