  18 class LocalProjectService {
  19   private dbPromise: Promise<IDBPDatabase<MyDB>> | null = null;
  20 
  21   private getDB(): Promise<IDBPDatabase<MyDB>> {
  22     // Delay DB initialization until it's actually needed on the client-side
  23     if (typeof window === 'undefined') {
  24       return new Promise(() => { }); // Return a promise that never resolves on the server
  25     }
  26 
  27     if (!this.dbPromise) {
  28       this.dbPromise = openDB<MyDB>(DB_NAME, DB_VERSION, {
  29         upgrade(db) {
  30           if (!db.objectStoreNames.contains(STORE_NAME)) {
  31             db.createObjectStore(STORE_NAME, { keyPath: 'id' });
  32           }
  33         },
  34       });
  35     }
  36     return this.dbPromise;
  37   }
  38 
  39   public async getAllProjects(): Promise<ProjectProperties[]> {
  40     const db = await this.getDB();
  41     const allProjects = await db.getAll(STORE_NAME);
  42     // Sort projects by updatedAt date in descending order
  43     return allProjects.sort((a, b) => {
  44       const dateA = a.meta?.updated ? new Date(a.meta.updated).getTime() : 0;
  45       const dateB = b.meta?.updated ? new Date(b.meta.updated).getTime() : 0;
  46       return dateB - dateA;
  47     });
  48   }
  49 
  50   public async getProject(id: string): Promise<ProjectProperties | undefined> {
  51     const db = await this.getDB();
  52     return db.get(STORE_NAME, id);
  53   }
  54 
  55   public async saveProject(project: ProjectProperties): Promise<ProjectProperties> {
  56     const db = await this.getDB();
  57     const projectToSave = {
  58       ...project,
  59       meta: { ...project.meta, updatedAt: new Date().toISOString() },
  60     };
  61     await db.put(STORE_NAME, projectToSave);
  62     return projectToSave;
  63   }
  64 
  65   public async deleteProject(id: string): Promise<void> {
